#include <cstdio>
#include <string>
#include <type_traits>

int main()
{
    constexpr bool reorderUsesReference =
        std::is_same_v<
            decltype(&approveReorder),
            void (*)(int&, int)
        >;

    constexpr bool descriptionUsesConstReference =
        std::is_same_v<
            decltype(&productDescriptionLength),
            std::size_t (*)(const std::string&)
        >;

    std::fprintf(
        stderr,
        "TRACE|ENTER_SCOPE|caller|retail replenishment request\n"
    );

    int reorderCount = 12;

    std::fprintf(
        stderr,
        "TRACE|CREATE_VALUE|reorderCount|type=int|value=%d\n",
        reorderCount
    );

    std::fprintf(
        stderr,
        "TRACE|ENTER_SCOPE|approveReorder|function call\n"
    );

    if constexpr (reorderUsesReference)
    {
        std::fprintf(
            stderr,
            "TRACE|BIND_ALIAS|parameterReorderCount|target=reorderCount|type=int&|const=false\n"
        );
    }
    else
    {
        std::fprintf(
            stderr,
            "TRACE|CREATE_VALUE|parameterReorderCount|type=int|value=%d\n",
            reorderCount
        );
    }

    approveReorder(
        reorderCount,
        8
    );

    std::fprintf(
        stderr,
        "TRACE|WRITE_VALUE|reorderCount|via=approveReorder|value=%d\n",
        reorderCount
    );

    std::fprintf(
        stderr,
        "TRACE|EXIT_SCOPE|approveReorder|function returned\n"
    );

    const std::string description =
        "Rechargeable work light";

    std::fprintf(
        stderr,
        "TRACE|CREATE_VALUE|description|type=std::string|value=Rechargeable work light\n"
    );

    std::fprintf(
        stderr,
        "TRACE|ENTER_SCOPE|productDescriptionLength|function call\n"
    );

    if constexpr (descriptionUsesConstReference)
    {
        std::fprintf(
            stderr,
            "TRACE|BIND_ALIAS|parameterDescription|target=description|type=const std::string&|const=true\n"
        );
    }
    else
    {
        std::fprintf(
            stderr,
            "TRACE|CREATE_VALUE|parameterDescription|type=std::string|value=Rechargeable work light\n"
        );
    }

    const std::size_t length =
        productDescriptionLength(
            description
        );

    std::fprintf(
        stderr,
        "TRACE|EXIT_SCOPE|productDescriptionLength|function returned\n"
    );

    std::fprintf(
        stderr,
        "TRACE|EXIT_SCOPE|caller|retail replenishment request completed\n"
    );

    if (reorderCount != 20)
    {
        std::fprintf(
            stderr,
            "Expected caller reorderCount to become 20, got %d.\n",
            reorderCount
        );

        return 2;
    }

    if (length != description.size())
    {
        return 3;
    }

    if (!reorderUsesReference)
    {
        return 4;
    }

    if (!descriptionUsesConstReference)
    {
        return 5;
    }

    return 0;
}
